        String safe = line.replaceAll("[\p{Cntrl}\u00a7]", "?");
        if (safe.length() <= MAX_LINE_CHARS) {
            return safe;
        }

        // Truncate while preserving UTF-16 surrogate pairs
        StringBuilder truncated = new StringBuilder();
        int length = 0;
        int limit = MAX_LINE_CHARS - 3;

        for (int i = 0; i < safe.length(); i += Character.charCount(codePoint)) {
            int codePoint = safe.codePointAt(i);
            int codePointLength = Character.charCount(codePoint);

            if (length + codePointLength > limit) {
                // Check if this code point is a high surrogate and the next is a low surrogate
                if (i + codePointLength < safe.length()) {
                    int nextCodePoint = safe.codePointAt(i + codePointLength);
                    if (Character.isHighSurrogate((char) codePoint) && Character.isLowSurrogate((char) nextCodePoint)) {
                        // Truncate before the high surrogate
                        i += codePointLength - 1;
                        break;
                    }
                }
                // Truncate here
                break;
            }

            truncated.appendCodePoint(codePoint);
            length += codePointLength;
        }

        return truncated.toString() + "...";
